<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>PUERTO FUEGO — Dani Reyes</title>
<!-- Inline favicon so the page makes zero network requests. -->
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' fill='%231a0f0a'/%3E%3Ctext x='32' y='44' font-size='36' text-anchor='middle' fill='%23ff8c2e' font-family='Georgia,serif'%3EP%3C/text%3E%3C/svg%3E">
<style>
  /* Dark, warm Puerto Fuego palette: burnt night, ember orange, sand. */
  :root {
    --night: #140d08;
    --ember: #ff8c2e;
    --ember-soft: #ffb35c;
    --sand: #e8cfa8;
    --sand-dim: #a98f6d;
