  #scene, #hud {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100%;
    display: block;
  }
  #scene { z-index: 0; }
  #hud { z-index: 1; pointer-events: none; }

  /* Boot splash: covers the screen until the game module reports ready. */
  #splash {
    position: fixed;
    inset: 0;
    z-index: 10;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 14px;
    text-align: center;
    padding: 24px;
    background:
      radial-gradient(ellipse 80% 55% at 50% 78%, rgba(255, 110, 20, 0.28), transparent 70%),
      linear-gradient(180deg, #1d1109 0%, #140d08 55%, #0d0705 100%);
    transition: opacity 0.6s ease;
  }
  #splash.hidden { opacity: 0; pointer-events: none; }
  #splash .kicker {
    letter-spacing: 0.5em;
    text-transform: uppercase;
    font-size: 12px;
    color: var(--sand-dim);
  }
  #splash h1 {
    font-size: clamp(44px, 9vw, 96px);
    line-height: 0.95;
    letter-spacing: 0.08em;
    color: var(--ember);
    text-shadow: 0 0 34px rgba(255, 140, 46, 0.45), 0 2px 0 rgba(0, 0, 0, 0.6);
  }
  #splash h1 span { display: block; color: var(--sand); font-size: 0.52em; letter-spacing: 0.34em; }
  #splash .premise {
    max-width: 560px;
    font-size: 16px;
    line-height: 1.6;
    color: var(--sand);
    font-style: italic;
  }
  #splash .premise strong { color: var(--ember-soft); font-style: normal; }
  #splash .status { font-size: 13px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--sand-dim); }
  #splash .bar {
    width: min(320px, 70vw);
    height: 3px;
    background: rgba(232, 207, 168, 0.18);
    border-radius: 2px;
    overflow: hidden;
  }
  #splash .bar i {
    display: block;
    height: 100%;
    width: 38%;
    background: var(--ember);
    border-radius: 2px;
    animation: slide 1.1s ease-in-out infinite alternate;
  }
  @keyframes slide { from { margin-left: 0; } to { margin-left: 62%; } }
  #splash .hint { font-size: 12px; color: var(--sand-dim); letter-spacing: 0.12em; }

  /* Boot failure: same splash, but the error is shown in plain text. */
  #splash.failed .bar { display: none; }
  #splash.failed h1 { font-size: clamp(28px, 5vw, 44px); }
  #boot-error {
    display: none;
    max-width: 640px;
    padding: 14px 18px;
    border: 1px solid var(--line);
    border-radius: 6px;
    background: var(--panel);
    color: var(--ember-soft);
    font-family: ui-monospace, 'Courier New', monospace;
    font-size: 13px;
    line-height: 1.5;
    text-align: left;
    white-space: pre-wrap;
    word-break: break-word;
  }
  #splash.failed #boot-error { display: block; }
