<body>
  <canvas id="scene"></canvas>
  <canvas id="hud"></canvas>

  <div id="splash" role="status" aria-live="polite">
    <div class="kicker">Welcome back to</div>
    <h1>PUERTO<br>FUEGO<span>OPEN WORLD</span></h1>
    <p class="premise">
      <strong>Dani Reyes</strong> came home to bury his brother — and found the city
      that killed him. Take the streets of Puerto Fuego back, one job, one
      crew, one score at a time.
    </p>
    <div class="bar" aria-hidden="true"><i></i></div>
    <div class="status" id="boot-status">Loading the city&hellip;</div>
    <pre id="boot-error"></pre>
    <div class="hint">WASD drive &middot; mouse look &middot; E interact &middot; M map</div>
  </div>

  <script type="module">
    // Boot the game. If the module fails to load (or throws while starting),
    // say so on the splash instead of leaving a silent black page: the
    // error text itself is shown so the failure can actually be fixed.
    const splash = document.getElementById('splash');
    const status = document.getElementById('boot-status');
    const errorBox = document.getElementById('boot-error');

    function showBootFailure(err) {
      const message = err instanceof Error ? (err.stack || err.message) : String(err);
      status.textContent = 'The city failed to load';
      errorBox.textContent = message;
      splash.classList.add('failed');
    }

    window.addEventListener('error', (event) => showBootFailure(event.error || event.message));
    window.addEventListener('unhandledrejection', (event) => showBootFailure(event.reason));

    try {
      const game = await import('./src/main.js');
      const start = game.start ?? game.default;
      if (typeof start !== 'function') {
        throw new Error('src/main.js exports no start() function');
      }
      await start({ scene: document.getElementById('scene'), hud: document.getElementById('hud') });
      status.textContent = 'Welcome to Puerto Fuego';
      splash.classList.add('hidden');
    } catch (err) {
      showBootFailure(err);
    }
  </script>
</body>
</html>
