        g.gain.linearRampToValueAtTime(0.09, now + 1.1);
        g.gain.linearRampToValueAtTime(0.0001, now + 2.2);
        src.connect(bp);
        bp.connect(g);
        g.connect(bed);
        src.start(now);
        src.stop(now + 2.3);
      };
      timers.push(setInterval(pass, 7000));
    }

