    const v = ambienceVoice;
    ambienceVoice = null;
    for (const timer of v.timers) clearInterval(timer);
    if (!ctx) return;
    const t = ctx.currentTime;
    v.bed.gain.setTargetAtTime(0.0001, t, 0.3);
