          if (typeof n.stop === 'function') n.stop();
        } catch {
          /* already stopped */
        }
        try {
          n.disconnect();
        } catch {
          /* already detached */
        }
      }
    };
    if (typeof setTimeout === 'function') setTimeout(kill, 900);
    else kill();
