  skin: 0xc98d63,
  skinDark: 0xb47a52,
  jacket: 0x2f4d70,
  jacketDark: 0x243c58,
  tee: 0x8f9aa4,
  pants: 0x23262f,
  hair: 0x241a14,
  shoe: 0x17171a,
