    if (!world) return out;
    const collect = (list, kind) => {
      if (!Array.isArray(list)) return;
      for (const item of list) {
        const p = item && item.position ? item.position : item;
        if (!p || !Number.isFinite(p.x) || !Number.isFinite(p.z)) continue;
        out.push({ x: p.x, z: p.z, kind });
