  }

  // --- screen elements -----------------------------------------------------

  function drawMissionCard() {
    if (!mission) return;
    const pad = 18 * s;
    const bw = Math.min(w * 0.44, 352 * s, Math.max(150 * s, w / 2 - 96 * s));
    const bh = 80 * s;
    const x = pad;
    const y = pad;

    chip(x, y, bw, bh, 7 * s, 'rgba(12, 14, 20, 0.78)', PAL.edgeWarm);
    // Amber spine: colour finds the panel in peripheral vision before a word
    // of it is read.
