    // the message is legible in the middle and never pops on or off.
    const alpha = clamp(Math.min((1 - life) / TOAST_EDGE, life / TOAST_EDGE), 0, 1);
    if (alpha <= 0.01) return;

    ctx.save();
    ctx.globalAlpha = alpha;
